      "phases": [],
      "strategy": "Chìa khóa của trận đánh là kiểm soát đám vine tentacle. Trong suốt trận, The Brambleghast liên tục triệu hồi các xúc tu dây leo tự động đập vào người chơi. Hãy phá hủy chúng để có thêm không gian di chuyển và né đòn, tránh bị dồn sát thương chồng chất. Khai thác điểm yếu Fire để tăng tốc độ hạ boss, và ưu tiên đánh tầm xa để giữ khoảng cách an toàn với các đòn cận chiến cùng AoE Slam chí mạng. Tận dụng cửa sổ khi boss bị kẹt tay sau đòn Creeping Roots để dồn sát thương.",
